template.script:
/* ============ PLAQUE D'ESSAI (simulateur Arduino) ============
   Gabarit circuit_plaque_essai â€” mÃªme logique que la webapp
   /sites/circuits, en vanilla pour rester dans Odoo : pile, LED,
   rÃ©sistance, interrupteur, fils. Propagation = BFS depuis la pile. */
(function () {
  var LB = 10, HB = 2;
  var TYPES = {
    pile: { nom: "Pile", sym: "9V" },
    led: { nom: "LED", sym: "\u25CF" },
    resistance: { nom: "RÃ©sistance", sym: "R" },
    interrupteur: { nom: "Interrupteur", sym: "\u21C4" }
  };
  var etat = { composants: [], fils: [], courant: {}, outil: "pile", choix: null };
  var elEtat = document.getElementById("bdc-etat");
  var elPlanche = document.getElementById("bdc-planche");
  var elPalette = document.getElementById("bdc-palette");
  if (!elPlanche || !elPalette) return;
  var nId = 0, cle = function (c, r) { return c + "," + r; };
  var composantA = function (c, r) {
    for (var i = 0; i < etat.composants.length; i++)
      if (etat.composants[i].col === c && etat.composants[i].rangee === r) return etat.composants[i];
    return null;
  };
  function relier(x, y, voisins) {
    var k1 = cle(x.col, x.rangee), k2 = cle(y.col, y.rangee);
    (voisins[k1] = voisins[k1] || new Set()).add(k2);
    (voisins[k2] = voisins[k2] || new Set()).add(k1);
  }
  function simuler() {
    var voisins = {};
    etat.fils.forEach(function (f) { relier(f.a, f.b, voisins); });
    etat.composants.forEach(function (c) {
      if (c.type !== "interrupteur" || c.etat)
        relier({ col: c.col, rangee: c.rangee }, { col: c.col + 1, rangee: c.rangee }, voisins);
    });
    var tension = {};
    var pile = etat.composants.filter(function (x) { return x.type === "pile"; })[0];
    if (pile) {
      var depart = cle(pile.col, pile.rangee), vus = {}, file = [depart];
      vus[depart] = true;
      while (file.length) {
        var k = file.shift(); tension[k] = true;
        (voisins[k] || []).forEach(function (n) { if (!vus[n]) { vus[n] = true; file.push(n); } });
      }
    }
    var courant = {};
    etat.composants.forEach(function (c) { courant[c.id] = c.type === "led" && !!tension[cle(c.col, c.rangee)]; });
    etat.fils.forEach(function (f, i) { courant["f" + i] = !!tension[cle(f.a.col, f.a.rangee)]; });
    etat.courant = courant;
  }
  function message() {
    if (!etat.composants.filter(function (x) { return x.type === "pile"; }).length) return "Place une pile pour commencer.";
    var leds = etat.composants.filter(function (x) { return x.type === "led"; });
    if (!leds.length) return "Ajoute une LED pour voir le courant passer.";
    var on = leds.filter(function (l) { return etat.courant[l.id]; });
    if (on.length === leds.length) return "Le circuit est fermÃ© â€” les LED s'allument.";
    if (!on.length) return "Les LED sont Ã©teintes : le circuit est ouvert ou interrompu.";
    return on.length + " LED allumÃ©e(s) sur " + leds.length;
  }
  function dessiner() {
    elEtat.textContent = message();
    elPlanche.innerHTML = "";
    var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
    svg.setAttribute("class", "bdc-fils");
    svg.setAttribute("viewBox", "0 0 " + (LB * 52) + " " + (HB * 52));
    etat.fils.forEach(function (f, i) {
      var ln = document.createElementNS("http://www.w3.org/2000/svg", "line");
      ln.setAttribute("x1", f.a.col * 52 + 26); ln.setAttribute("y1", f.a.rangee * 52 + 26);
      ln.setAttribute("x2", f.b.col * 52 + 26); ln.setAttribute("y2", f.b.rangee * 52 + 26);
      ln.setAttribute("class", "bdc-fil" + (etat.courant["f" + i] ? " vif" : ""));
      svg.appendChild(ln);
    });
    var r, c;
    for (r = 0; r < HB; r++) {
      var rangee = document.createElement("div");
      rangee.setAttribute("class", "bdc-rangee");
      for (c = 0; c < LB; c++) {
        var btn = document.createElement("button");
        btn.setAttribute("type", "button");
        btn.setAttribute("class", "bdc-case");
        if (etat.fils.some(function (f, i) { return etat.courant["f" + i] &&
            ((f.a.col === c && f.a.rangee === r) || (f.b.col === c && f.b.rangee === r)); }))
          btn.classList.add("vif");
        if (etat.choix && etat.choix.col === c && etat.choix.rangee === r) btn.classList.add("choix");
        var comp = composantA(c, r);
        if (comp) {
          var sp = document.createElement("span");
          sp.setAttribute("class", "bdc-part " + comp.type +
            (comp.type === "led" && etat.courant[comp.id] ? " allume" : ""));
          sp.textContent = comp.type === "interrupteur" ? (comp.etat ? "1" : "0") : TYPES[comp.type].sym;
          sp.addEventListener("click", function (ev, co) {
            ev.stopPropagation();
            if (etat.outil === "interrupteur" && co.type === "interrupteur") { co.etat = !co.etat; simuler(); dessiner(); }
            else if (etat.outil === "main") { etat.composants = etat.composants.filter(function (x) { return x.id !== co.id; }); simuler(); dessiner(); }
          }.bind(null, null, comp));
          btn.appendChild(sp);
        }
        (function (col, rangee) {
          btn.addEventListener("click", function () { cliquer(col, rangee); });
        })(c, r);
        rangee.appendChild(btn);
      }
      elPlanche.appendChild(rangee);
    }
    elPlanche.appendChild(svg);
  }
  function cliquer(col, rangee) {
    if (etat.outil === "fil") {
      if (etat.choix) {
        if (etat.choix.col === col && etat.choix.rangee === rangee) { etat.choix = null; dessiner(); return; }
        etat.fils.push({ a: { col: etat.choix.col, rangee: etat.choix.rangee }, b: { col: col, rangee: rangee } });
        etat.choix = null; simuler(); dessiner(); return;
      }
      etat.choix = { col: col, rangee: rangee }; dessiner(); return;
    }
    var occ = composantA(col, rangee);
    if (occ) {
      if (etat.outil === "main") { etat.composants = etat.composants.filter(function (x) { return x.id !== occ.id; }); simuler(); dessiner(); }
      return;
    }
    etat.composants.push({ id: "p" + (nId++), type: etat.outil, col: col, rangee: rangee, etat: false });
    simuler(); dessiner();
  }
  Object.keys(TYPES).forEach(function (k) {
    var b = document.createElement("button");
    b.setAttribute("type", "button");
    b.setAttribute("class", "bdc-btn" + (etat.outil === k ? " on" : ""));
    b.innerHTML = TYPES[k].sym + " " + TYPES[k].nom;
    b.addEventListener("click", function () { etat.outil = k; etat.choix = null; dessiner(); });
    elPalette.appendChild(b);
  });
  ["fil", "main"].forEach(function (k) {
    var b = document.createElement("button");
    b.setAttribute("type", "button");
    b.setAttribute("class", "bdc-btn" + (etat.outil === k ? " on" : ""));
    b.textContent = k === "fil" ? "â› Fil" : "âœ• Retirer";
    b.addEventListener("click", function () { etat.outil = k; etat.choix = null; dessiner(); });
    elPalette.appendChild(b);
  });
  dessiner();
})();
